<template>
  <div class="notes-workspace" v-loading="loading">
    <aside class="notebook-sidebar">
      <div class="brand"><span class="brand-icon"><el-icon><Notebook /></el-icon></span><div><b>学习笔记</b><small>我的知识空间</small></div></div>
      <button class="new-page" @click="openCreate"><el-icon><Plus /></el-icon>新建页面<kbd>Ctrl N</kbd></button>
      <div class="label">笔记本</div><button class="notebook active"><i></i>我的学习笔记</button>
      <div class="label">分区</div>
      <button v-for="s in sections" :key="s.id" class="section" :class="{selected: activeSection === s.id}" @click="activeSection = s.id"><i :style="{background:s.color}"></i><span>{{ s.title }}</span><em>{{ s.count }}</em></button>
      <p v-if="!sections.length" class="hint">创建页面后自动生成分区</p><footer>{{ notes.length }} 个页面</footer>
    </aside>
    <aside v-if="navOpen" class="pages-sidebar picker-backdrop" @click.self="navOpen = false">
      <div class="picker-card">
      <header><div><small>{{ activeSectionTitle }}</small><h1>页面</h1></div><el-button circle text @click="openCreate"><el-icon><Plus /></el-icon></el-button></header>
      <el-input v-model="keyword" placeholder="搜索页面" clearable class="search"><template #prefix><el-icon><Search /></el-icon></template></el-input>
      <div class="pages-list"><section v-for="group in noteGroups" :key="group.id" class="course-group"><header class="course-group-title"><i :style="{background:group.color}"></i><b>{{ group.title }}</b><em>{{ group.notes.length }}</em></header><button v-for="n in group.notes" :key="n.id" class="page" :class="{selected:selected?.id===n.id}" @click="select(n); navOpen = false"><el-icon><Document /></el-icon><span><b>{{ n.title || '无标题页面' }}</b><small>{{ summary(n.content) || '空白页面' }}</small><time>{{ date(n.updated_at || n.created_at) }}</time></span></button></section><div v-if="!noteGroups.length" class="empty-pages"><el-icon :size="28"><DocumentAdd /></el-icon><p>还没有页面</p><button @click="openCreate">创建第一篇笔记</button></div></div>
      </div>
    </aside>
    <main class="editor-area">
      <template v-if="selected">
        <header class="editor-header"><div class="header-left"><el-button class="nav-toggle" text circle title="打开页面导航" @click="navOpen = !navOpen"><el-icon><Menu /></el-icon></el-button><span class="crumb">我的学习笔记 / {{ courseName(selected.course_id) }}</span></div><span class="save-state">{{ saving ? '正在保存…' : '✓ 已保存' }} <el-dropdown @command="remove"><el-button text circle><el-icon><MoreFilled /></el-icon></el-button><template #dropdown><el-dropdown-menu><el-dropdown-item command="delete" class="danger">删除页面</el-dropdown-item></el-dropdown-menu></template></el-dropdown></span></header>
        <article class="editor-scroll"><input v-model="title" class="title" placeholder="无标题页面" @input="scheduleSave" /><div class="meta">{{ date(selected.updated_at || selected.created_at) }} 更新 · {{ courseName(selected.course_id) }}</div>
          <div class="toolbar"><el-tooltip content="加粗"><button @click="cmd('bold')"><b>B</b></button></el-tooltip><el-tooltip content="斜体"><button @click="cmd('italic')"><i>I</i></button></el-tooltip><el-tooltip content="下划线"><button @click="cmd('underline')"><u>U</u></button></el-tooltip><span></span><el-tooltip content="标题"><button @click="block('h2')">H</button></el-tooltip><el-tooltip content="项目符号列表"><button @click="cmd('insertUnorderedList')">☷</button></el-tooltip><el-tooltip content="编号列表"><button @click="cmd('insertOrderedList')">☰</button></el-tooltip><span></span><label class="toolbar-select" title="字体类型"><span>字体</span><select @change="fontFamily"><option value="inherit">默认</option><option value="Microsoft YaHei">微软雅黑</option><option value="SimSun">宋体</option><option value="SimHei">黑体</option><option value="KaiTi">楷体</option><option value="FangSong">仿宋</option></select></label><label class="toolbar-select" title="字体大小"><span>字号</span><select @change="fontSize"><option value="3">默认</option><option value="2">小</option><option value="4">大</option><option value="5">特大</option></select></label><label class="toolbar-color" title="字体颜色"><span>文字</span><input type="color" value="#334155" @input="fontColor" /></label><div class="tag-palette" title="选择标签颜色"><span>标签</span><button v-for="tag in tagColors" :key="tag.value" type="button" class="tag-swatch" :style="{background:tag.value}" :title="tag.name" @mousedown.prevent="applyTagColor(tag.value)"></button></div><span></span><el-tooltip content="插入图片"><button @click="imageInput?.click()"><el-icon><Picture /></el-icon></button></el-tooltip><input ref="imageInput" hidden type="file" accept="image/*" @change="insertImage" /></div>
<div ref="editor" class="rich-editor" contenteditable="true" spellcheck="false" @input="onInput" @compositionstart="compositionStart" @compositionend="compositionEnd" @paste="pasteImage" @dragstart="dragImageStart" @dragover.prevent @drop="dropImage" @mousedown="beginImageDrag"></div>
          <div class="properties"><label>课程<el-select v-model="courseId" size="small" @change="loadKps(courseId)"><el-option v-for="c in courses" :key="c.id" :label="c.title" :value="c.id" /></el-select></label><label>知识点<el-select v-model="kpId" size="small" clearable @change="scheduleSave"><el-option v-for="k in kps" :key="k.id" :label="k.name" :value="k.id" /></el-select></label><label>标签<el-input v-model="tags" size="small" placeholder="重点、易错" @input="scheduleSave" /></label></div>
        </article>
      </template><div v-else class="editor-empty"><el-button class="empty-nav-button" text @click="navOpen = true"><el-icon><Menu /></el-icon>浏览页面</el-button><el-icon :size="40"><Notebook /></el-icon><h2>选择一篇笔记开始学习</h2><p>记录文字、图片和你的学习灵感</p><el-button type="primary" @click="openCreate"><el-icon><Plus /></el-icon>新建页面</el-button></div>
    </main>
    <el-dialog v-model="dialog" title="新建学习页面" width="430px"><el-form label-position="top"><el-form-item label="所属课程" required><el-select v-model="newPage.course_id" style="width:100%" placeholder="选择课程" @change="loadKps(newPage.course_id)"><el-option v-for="c in courses" :key="c.id" :label="c.title" :value="c.id" /></el-select></el-form-item><el-form-item label="关联知识点"><el-select v-model="newPage.knowledge_point_id" clearable style="width:100%"><el-option v-for="k in kps" :key="k.id" :label="k.name" :value="k.id" /></el-select></el-form-item><el-form-item label="页面标题"><el-input v-model="newPage.title" placeholder="例如：Python 变量与数据类型" /></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="create">创建页面</el-button></template></el-dialog>
  </div>
</template>
<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, onMounted, ref } from 'vue'
import { Document, DocumentAdd, Menu, MoreFilled, Notebook, Picture, Plus, Search } from '@element-plus/icons-vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { useAuthStore } from '@/stores/auth'; import { notesAPI, type Note } from '@/api/notes'; import { coursesAPI, type CourseItem, type KnowledgePointItem } from '@/api/courses'
const auth=useAuthStore(); const notes=ref<Note[]>([]); const courses=ref<CourseItem[]>([]); const kps=ref<KnowledgePointItem[]>([]); const loading=ref(false); const saving=ref(false); const keyword=ref(''); const activeSection=ref('all'); const navOpen=ref(false); const composing=ref(false); const selected=ref<Note|null>(null); const editor=ref<HTMLElement|null>(null); const imageInput=ref<HTMLInputElement|null>(null); const dialog=ref(false); const title=ref(''); const content=ref(''); const tags=ref(''); const courseId=ref<number>(); const kpId=ref<number>(); const savedRange=ref<Range|null>(null); const tagColors=[{name:'无背景色',value:'#ffffff'},{name:'黄色',value:'#fef3c7'},{name:'蓝色',value:'#dbeafe'},{name:'绿色',value:'#dcfce7'},{name:'红色',value:'#fee2e2'},{name:'紫色',value:'#ede9fe'}]; const newPage=ref({course_id:undefined as number|undefined,knowledge_point_id:undefined as number|undefined,title:''}); let timer:ReturnType<typeof setTimeout>|undefined
function courseName(id?:number){return courses.value.find(c=>c.id===id)?.title||'未分类课程'} function summary(v:string){return (v||'').replace(/<[^>]+>/g,' ').replace(/\s+/g,' ').trim()} function date(v:string){return v?new Date(v).toLocaleDateString('zh-CN',{month:'short',day:'numeric'}):''}
const sections=computed(()=>{const map=new Map<number,any>(); const colors=['#3b82f6','#10b981','#f59e0b','#8b5cf6','#ef4444']; notes.value.forEach(n=>{if(!map.has(n.course_id))map.set(n.course_id,{id:String(n.course_id),title:courseName(n.course_id),count:0,color:colors[map.size%colors.length]});map.get(n.course_id).count++});return [...map.values()]})
const activeSectionTitle=computed(()=>activeSection.value==='all'?'我的笔记本':courseName(Number(activeSection.value))); const filteredNotes=computed(()=>{let a=notes.value;if(activeSection.value!=='all')a=a.filter(n=>String(n.course_id)===activeSection.value);const q=keyword.value.toLowerCase().trim();return q?a.filter(n=>`${n.title} ${n.content} ${n.tags}`.toLowerCase().includes(q)):a}); const noteGroups=computed(()=>{const map=new Map<number,{id:string,title:string,color:string,notes:Note[]}>();const colors=['#2563eb','#16a34a','#ea580c','#7c3aed','#db2777'];filteredNotes.value.forEach(n=>{if(!map.has(n.course_id))map.set(n.course_id,{id:String(n.course_id),title:courseName(n.course_id),color:colors[map.size%colors.length],notes:[]});map.get(n.course_id)!.notes.push(n)});return [...map.values()]})
async function load(){loading.value=true;try{notes.value=await notesAPI.list();if(!selected.value&&notes.value[0])select(notes.value[0])}finally{loading.value=false}} async function loadCourses(){try{courses.value=await coursesAPI.getList()}catch{}} async function loadKps(id?:number){if(!id)return;try{kps.value=(await coursesAPI.getDetail(id)).knowledge_points||[]}catch{kps.value=[]}}
function select(n:Note){selected.value=n;title.value=n.title;content.value=n.content||'';tags.value=n.tags||'';courseId.value=n.course_id;kpId.value=n.knowledge_point_id||undefined;loadKps(n.course_id);nextTick(()=>{if(editor.value){editor.value.innerHTML=content.value;normalizeImages()}})}
function openCreate(){newPage.value={course_id:courses.value[0]?.id,knowledge_point_id:undefined,title:''};if(newPage.value.course_id)loadKps(newPage.value.course_id);dialog.value=true} async function create(){if(!newPage.value.course_id){ElMessage.warning('请先选择课程');return}if(!newPage.value.title.trim()){ElMessage.warning('请填写页面标题');return}try{const n=await notesAPI.create({course_id:newPage.value.course_id,knowledge_point_id:newPage.value.knowledge_point_id||0,title:newPage.value.title.trim(),content:'<p>开始记录你的学习内容…</p>'});notes.value.unshift(n);dialog.value=false;select(n);ElMessage.success('页面已创建')}catch{ElMessage.error('创建失败')}}
let dragState:{node:HTMLElement;offsetX:number;offsetY:number}|null=null; function beginImageDrag(e:MouseEvent){const target=(e.target as HTMLElement)?.closest('.note-image') as HTMLElement|null;if(!target||e.button!==0)return;if((e.target as HTMLElement).tagName==='IMG'){e.preventDefault();const root=editor.value;if(!root)return;const rootRect=root.getBoundingClientRect();const rect=target.getBoundingClientRect();target.style.position='absolute';target.style.left=(rect.left-rootRect.left+root.scrollLeft)+'px';target.style.top=(rect.top-rootRect.top+root.scrollTop)+'px';dragState={node:target,offsetX:e.clientX-rect.left,offsetY:e.clientY-rect.top};document.addEventListener('mousemove',moveImage);document.addEventListener('mouseup',endImage)}} function moveImage(e:MouseEvent){if(!dragState||!editor.value)return;const rootRect=editor.value.getBoundingClientRect();dragState.node.style.left=(e.clientX-rootRect.left-dragState.offsetX+editor.value.scrollLeft)+'px';dragState.node.style.top=(e.clientY-rootRect.top-dragState.offsetY+editor.value.scrollTop)+'px';onInput()} function endImage(){dragState=null;document.removeEventListener('mousemove',moveImage);document.removeEventListener('mouseup',endImage)} function rememberSelection(){const selection=window.getSelection();if(selection?.rangeCount&&editor.value?.contains(selection.anchorNode))savedRange.value=selection.getRangeAt(0).cloneRange()} function restoreSelection(){if(!savedRange.value)return;const selection=window.getSelection();selection?.removeAllRanges();selection?.addRange(savedRange.value)} let draggedImage: HTMLElement|null=null; function normalizeImages(){const root=editor.value;if(!root)return;root.querySelectorAll('img').forEach(img=>{if(img.parentElement?.classList.contains('note-image'))return;const wrap=document.createElement('span');wrap.className='note-image';wrap.contentEditable='false';wrap.draggable=true;img.parentNode?.insertBefore(wrap,img);wrap.appendChild(img)})} function dragImageStart(e:DragEvent){const target=(e.target as HTMLElement)?.closest('.note-image') as HTMLElement|null;if(target&&e.dataTransfer){draggedImage=target;e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain','note-image')}} function dropImage(e:DragEvent){const target=(e.target as HTMLElement)?.closest('.note-image');if(target)return;const dragged=draggedImage;if(dragged){const range=document.caretRangeFromPoint?.(e.clientX,e.clientY);if(range){range.deleteContents();range.insertNode(dragged);onInput()}}} function onInput(){normalizeImages();if(composing.value)return;const html=editor.value?.innerHTML||'';if(editor.value&&!(editor.value.textContent||'').trim()){editor.value.innerHTML='';content.value=''}else{content.value=html}scheduleSave()} function compositionStart(){composing.value=true} function compositionEnd(){composing.value=false;onInput()} function scheduleSave(){if(!selected.value)return;clearTimeout(timer);timer=setTimeout(save,700)} async function save(){if(!selected.value)return;saving.value=true;try{const n=await notesAPI.update(selected.value.id,{title:title.value||'无标题页面',content:content.value,tags:tags.value});selected.value=n;const i=notes.value.findIndex(x=>x.id===n.id);if(i>=0)notes.value[i]=n}finally{saving.value=false}}
function cmd(c:string){document.execCommand(c);onInput();editor.value?.focus()} function block(t:string){document.execCommand('formatBlock',false,t);onInput();editor.value?.focus()} function fontFamily(e:Event){const value=(e.target as HTMLSelectElement).value;restoreSelection();editor.value?.focus();document.execCommand('fontName',false,value);onInput()} function fontSize(e:Event){const value=(e.target as HTMLSelectElement).value;restoreSelection();editor.value?.focus();document.execCommand('fontSize',false,value);onInput()} function fontColor(e:Event){const value=(e.target as HTMLInputElement).value;restoreSelection();editor.value?.focus();document.execCommand('foreColor',false,value);onInput()} function applyTagColor(value:string){const root=editor.value;if(!root)return;const selection=window.getSelection();if(selection?.rangeCount&&selection.toString()){document.execCommand('backColor',false,value);onInput();return}const caret=selection?.anchorNode;if(caret){const el=(caret.nodeType===Node.TEXT_NODE?caret.parentElement:caret) as HTMLElement|null;const line=el?.closest('p,div,h1,h2,h3,li,blockquote') as HTMLElement|null;if(line&&line!==root){line.style.backgroundColor=value;line.style.borderRadius='6px';line.style.padding='0';line.style.margin='0';line.style.width='100%';line.style.boxSizing='border-box';onInput()}}} function insertImage(e:Event){const f=(e.target as HTMLInputElement).files?.[0];if(!f)return;const r=new FileReader();r.onload=()=>{document.execCommand('insertHTML',false,`<img src="${r.result}" alt="${f.name}">`);onInput()};r.readAsDataURL(f)} function pasteImage(e:ClipboardEvent){const i=[...(e.clipboardData?.items||[])].find(x=>x.type.startsWith('image/'));if(!i)return;e.preventDefault();const f=i.getAsFile();if(f){const r=new FileReader();r.onload=()=>{document.execCommand('insertHTML',false,`<img src="${r.result}" alt="粘贴图片">`);onInput()};r.readAsDataURL(f)}}
async function remove(c:string){if(c!=='delete'||!selected.value)return;try{await ElMessageBox.confirm('确定删除这篇页面吗？','删除页面',{type:'warning'});const id=selected.value.id;await notesAPI.remove(id);notes.value=notes.value.filter(n=>n.id!==id);selected.value=filteredNotes.value[0]||null;if(selected.value)select(selected.value)}catch{}} function key(e:KeyboardEvent){if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='n'){e.preventDefault();openCreate()}} onMounted(()=>{load();loadCourses();window.addEventListener('keydown',key);document.addEventListener('selectionchange',rememberSelection)});onBeforeUnmount(()=>{window.removeEventListener('keydown',key);document.removeEventListener('selectionchange',rememberSelection);clearTimeout(timer)})
</script>
